// HasSheep applies the HasEdge predicate on the "sheep" edge.
func HasSheep() predicate.Task {
	return predicate.Task(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SheepTable, SheepColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSheepWith applies the HasEdge predicate on the "sheep" edge with a given conditions (other predicates).
func HasSheepWith(preds ...predicate.Sheep) predicate.Task {
	return predicate.Task(func(s *sql.Selector) {
		step := newSheepStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

